<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html,body{background:transparent;font-family:'Nunito',sans-serif}

:root{
  --bg:#fefbff;--sur:#f8f0fe;--sur2:#f0e5fd;
  --pur:#9b59d4;--pur-l:#c084fc;--pur-xl:#e9d5ff;
  --pink:#e879a0;--pink-l:#fce7f3;
  --blue-l:#dbeafe;--blue:#60a5fa;
  --gold:#f59e0b;--gold-l:#fef3c7;
  --red:#ef4444;
  --grn:#22c55e;
  --txt:#3d1f5e;--sub:#8b6ab0;--muted:#c4a8e0;
  --r:14px;--rs:8px;
}

#lcraw{display:none}
#lc{
  max-width:420px;margin:8px auto;
  background:var(--bg);
  border-radius:var(--r);
  border:1.5px solid rgba(192,132,252,.22);
  box-shadow:0 4px 28px rgba(140,80,220,.1),0 1px 4px rgba(140,80,220,.08);
  overflow:hidden;
  animation:lup .3s cubic-bezier(.22,.68,0,1.1) both;
}
@keyframes lup{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}

/* ─ HEADER ─ */
.lh{
  display:flex;justify-content:space-between;align-items:center;
  padding:10px 14px;
  background:linear-gradient(120deg,#ede9fe 0%,#fce7f3 50%,#dbeafe 100%);
  cursor:pointer;user-select:none;
  border-bottom:1px solid rgba(192,132,252,.18);
  transition:opacity .15s;
}
.lh:hover{opacity:.92}
.lh-l{display:flex;align-items:center;gap:8px}
.live-ring{position:relative;width:10px;height:10px;flex-shrink:0}
.live-dot{
  width:10px;height:10px;border-radius:50%;
  background:var(--red);display:block;
  position:relative;z-index:1;
}
.live-ping{
  position:absolute;inset:-3px;border-radius:50%;
  background:var(--red);opacity:.35;
  animation:ping 1.8s cubic-bezier(0,0,.2,1) infinite;
}
@keyframes ping{0%{transform:scale(1);opacity:.35}100%{transform:scale(2.2);opacity:0}}
.live-badge{
  font-size:9px;font-weight:800;letter-spacing:1.5px;
  padding:2px 7px;border-radius:99px;
  background:var(--red);color:#fff;text-transform:uppercase;
}
.offline-badge{
  font-size:9px;font-weight:800;letter-spacing:1.5px;
  padding:2px 7px;border-radius:99px;
  background:#9ca3af;color:#fff;text-transform:uppercase;
}
.stream-title{
  font-size:12.5px;font-weight:700;color:var(--txt);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:180px;
}
.lh-r{display:flex;align-items:center;gap:8px}
.viewer-pill{
  display:flex;align-items:center;gap:4px;
  font-size:11px;font-weight:700;color:var(--sub);
  background:rgba(255,255,255,.65);
  padding:3px 8px;border-radius:99px;
}
.viewer-pill svg{width:12px;height:12px;fill:var(--sub)}
.toggle-icon{
  width:20px;height:20px;display:flex;align-items:center;justify-content:center;
  border-radius:50%;background:rgba(255,255,255,.5);
  font-size:10px;color:var(--sub);transition:transform .22s;
}
.toggle-icon.open{transform:rotate(180deg)}

/* ─ BODY ─ */
.lb{
  max-height:0;overflow:hidden;
  transition:max-height .3s cubic-bezier(.4,0,.2,1);
}
.lb.open{max-height:520px}

/* ─ TABS ─ */
.tabs{
  display:flex;gap:0;
  padding:8px 10px 0;
  background:var(--sur);
  border-bottom:1px solid rgba(192,132,252,.14);
}
.tab-btn{
  flex:1;padding:7px 4px 8px;
  font-family:'Nunito',sans-serif;font-size:11px;font-weight:700;
  color:var(--muted);border:none;background:transparent;cursor:pointer;
  border-bottom:2px solid transparent;margin-bottom:-1px;
  transition:all .18s;
}
.tab-btn:hover{color:var(--sub)}
.tab-btn.on{color:var(--pur);border-bottom-color:var(--pur)}

/* ─ CONTENT ─ */
.tc{display:none;max-height:340px;overflow-y:auto}
.tc.vis{display:block}
.tc::-webkit-scrollbar{width:4px}
.tc::-webkit-scrollbar-track{background:transparent}
.tc::-webkit-scrollbar-thumb{background:rgba(192,132,252,.3);border-radius:4px}

/* ─ CHAT ─ */
.chat-list{padding:8px 10px;display:flex;flex-direction:column;gap:2px}
.chat-empty{padding:24px;text-align:center;font-size:12px;color:var(--muted)}
.cm{
  display:flex;align-items:flex-start;gap:6px;
  padding:4px 6px;border-radius:var(--rs);
  transition:background .12s;
}
.cm:hover{background:rgba(192,132,252,.07)}
.cm-badge{font-size:12px;flex-shrink:0;line-height:1.4}
.cm-name{
  font-size:11.5px;font-weight:800;white-space:nowrap;flex-shrink:0;
}
.cm-sep{font-size:10px;color:var(--muted);margin:0 1px}
.cm-msg{font-size:12px;font-weight:500;color:var(--txt);line-height:1.5;word-break:break-word}

/* ─ DONATE ─ */
.don-list{padding:8px 10px;display:flex;flex-direction:column;gap:8px}
.don-empty{padding:24px;text-align:center;font-size:12px;color:var(--muted)}
.don-card{
  border-radius:var(--rs);padding:10px 12px;
  background:linear-gradient(135deg,#fff7ed,#fce7f3);
  border:1.5px solid rgba(245,158,11,.2);
  position:relative;overflow:hidden;
}
.don-card::before{
  content:'';position:absolute;left:0;top:0;bottom:0;width:3px;
  background:linear-gradient(180deg,var(--gold),var(--pink));
}
.don-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:4px}
.don-name{font-size:12px;font-weight:800;color:var(--txt)}
.don-amount{
  font-size:13px;font-weight:900;
  background:linear-gradient(135deg,#f59e0b,#ec4899);
  -webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;
}
.don-msg{
  font-size:11px;font-weight:500;color:var(--sub);
  font-style:italic;line-height:1.45;
}
.don-time{font-size:9.5px;color:var(--muted);margin-top:3px}

/* ─ TOP DONORS ─ */
.top-list{padding:8px 10px;display:flex;flex-direction:column;gap:6px}
.top-empty{padding:24px;text-align:center;font-size:12px;color:var(--muted)}
.top-item{
  display:flex;align-items:center;gap:10px;
  padding:9px 12px;border-radius:var(--rs);
  background:var(--sur);border:1px solid rgba(192,132,252,.14);
  transition:background .12s;
}
.top-item:hover{background:var(--sur2)}
.top-rank{font-size:16px;width:24px;text-align:center;flex-shrink:0}
.top-name{flex:1;font-size:13px;font-weight:700;color:var(--txt)}
.top-total{
  font-size:12.5px;font-weight:800;color:var(--gold);
}
.top-bar-wrap{width:60px;height:4px;background:rgba(192,132,252,.15);border-radius:2px;overflow:hidden}
.top-bar{height:100%;border-radius:2px;background:linear-gradient(90deg,var(--pur-l),var(--pink))}

/* ─ FOOTER ─ */
.lf{
  padding:5px 12px 7px;
  background:var(--sur);
  border-top:1px solid rgba(192,132,252,.12);
  display:flex;justify-content:space-between;align-items:center;
}
.lf-label{font-size:8.5px;font-weight:700;letter-spacing:1.5px;color:var(--muted);text-transform:uppercase}
.lf-total{font-size:9px;font-weight:700;color:var(--sub)}
</style>
</head>
