<textarea id="lcraw">$1</textarea>
<div id="lc">

  <!-- HEADER -->
  <div class="lh" id="lc-hdr" onclick="LC.toggle()">
    <div class="lh-l">
      <div class="live-ring" id="live-ring">
        <div class="live-ping" id="live-ping"></div>
        <div class="live-dot" id="live-dot"></div>
      </div>
      <div class="live-badge" id="live-status-badge">LIVE</div>
      <div class="stream-title" id="lc-title">Loading...</div>
    </div>
    <div class="lh-r">
      <div class="viewer-pill">
        <svg viewBox="0 0 20 20"><path d="M10 12a2 2 0 100-4 2 2 0 000 4z"/><path fill-rule="evenodd" d="M.458 10C1.732 5.943 5.522 3 10 3s8.268 2.943 9.542 7c-1.274 4.057-5.064 7-9.542 7S1.732 14.057.458 10zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clip-rule="evenodd"/></svg>
        <span id="lc-viewers">0</span>
      </div>
      <div class="toggle-icon" id="lc-toggle-ic">▾</div>
    </div>
  </div>

  <!-- BODY (expandable) -->
  <div class="lb" id="lc-body">

    <!-- TABS -->
    <div class="tabs">
      <button class="tab-btn on" data-tab="chat" onclick="LC.tab('chat')">💬 Chat</button>
      <button class="tab-btn" data-tab="donate" onclick="LC.tab('donate')">💎 Donate</button>
      <button class="tab-btn" data-tab="top" onclick="LC.tab('top')">🏆 Top 5</button>
    </div>

    <!-- CHAT -->
    <div class="tc vis" id="tc-chat">
      <div class="chat-list" id="lc-chat">
        <div class="chat-empty">No messages yet ✨</div>
      </div>
    </div>

    <!-- DONATE -->
    <div class="tc" id="tc-donate">
      <div class="don-list" id="lc-donate">
        <div class="don-empty">No donations yet 💌</div>
      </div>
    </div>

    <!-- TOP 5 -->
    <div class="tc" id="tc-top">
      <div class="top-list" id="lc-top">
        <div class="top-empty">No donors yet 🎀</div>
      </div>
    </div>

    <!-- FOOTER -->
    <div class="lf">
      <div class="lf-label" id="lf-label">Live Stream</div>
      <div class="lf-total" id="lf-total"></div>
    </div>

  </div><!-- lb -->
</div><!-- #lc -->

<script>
var RANKS=['🥇','🥈','🥉','4th','5th'];
var BADGES={subscriber:'💜',moderator:'🛡️',vip:'⭐',member:'💚',partner:'✅'};
var COLORS=['#9b59d4','#e879a0','#3b82f6','#10b981','#f59e0b','#ef4444','#8b5cf6','#06b6d4','#ec4899','#84cc16'];

function g(id){return document.getElementById(id)}

function hashColor(str){
  var h=0;for(var i=0;i<str.length;i++)h=str.charCodeAt(i)+((h<<5)-h);
  return COLORS[Math.abs(h)%COLORS.length];
}

function fmtViewers(n){
  if(n>=1000000)return(n/1000000).toFixed(1)+'M';
  if(n>=1000)return(n/1000).toFixed(1)+'K';
  return n+'';
}

function fmtAmt(amt,cur){
  cur=cur||'¥';
  if(typeof amt==='number')return cur+(amt>=1000?(amt/1000).toFixed(amt%1000?1:0)+'K':amt.toLocaleString());
  return cur+(amt||'?');
}

var LC={
  open:false,
  currentTab:'chat',
  toggle:function(){
    LC.open=!LC.open;
    g('lc-body').classList.toggle('open',LC.open);
    g('lc-toggle-ic').classList.toggle('open',LC.open);
  },
  tab:function(t){
    LC.currentTab=t;
    document.querySelectorAll('.tab-btn').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-tab')===t)});
    ['chat','donate','top'].forEach(function(id){
      g('tc-'+id).classList.toggle('vis',id===t);
    });
  },
  init:function(){
    var raw=g('lcraw');if(!raw)return;
    var txt=raw.value.trim();if(!txt)return;
    var d;try{d=JSON.parse(txt)}catch(e){
      g('lc-title').textContent='Live Stream';
      LC.toggle();return;
    }

    // ─ HEADER ─
    var isLive=(d.status||'').toLowerCase()==='live';
    var dot=g('live-dot');var ping=g('live-ping');var badge=g('live-status-badge');
    if(isLive){
      dot.style.background='#ef4444';ping.style.display='block';
      badge.className='live-badge';badge.textContent='LIVE';
    } else {
      dot.style.background='#9ca3af';ping.style.display='none';
      badge.className='offline-badge';badge.textContent=(d.status||'OFFLINE').toUpperCase();
    }
    g('lc-title').textContent=d.title||'Live Stream';
    g('lc-viewers').textContent=fmtViewers(d.viewers||0);

    // ─ CHAT ─
    var chatEl=g('lc-chat');
    var msgs=d.chat||[];
    if(msgs.length){
      chatEl.innerHTML='';
      msgs.forEach(function(m){
        var color=m.color||hashColor(m.user||'anon');
        var badge=m.badge&&BADGES[m.badge]?'<span class="cm-badge">'+BADGES[m.badge]+'</span>':'';
        var row=document.createElement('div');row.className='cm';
        row.innerHTML=badge+'<span class="cm-name" style="color:'+color+'">'+esc(m.user||'anon')+'</span><span class="cm-sep">:</span><span class="cm-msg">'+esc(m.msg||'')+'</span>';
        chatEl.appendChild(row);
      });
      // auto-scroll to bottom
      chatEl.scrollTop=chatEl.scrollHeight;
    }

    // ─ DONATE ─
    var donEl=g('lc-donate');
    var dons=d.donations||[];
    if(dons.length){
      donEl.innerHTML='';
      dons.forEach(function(don){
        var card=document.createElement('div');card.className='don-card';
        var timeHtml=don.time?'<div class="don-time">'+esc(don.time)+'</div>':'';
        var msgHtml=don.msg?'<div class="don-msg">"'+esc(don.msg)+'"</div>':'';
        card.innerHTML='<div class="don-top"><span class="don-name">💎 '+esc(don.user||'Anonymous')+'</span><span class="don-amount">'+fmtAmt(don.amount,don.currency)+'</span></div>'+msgHtml+timeHtml;
        donEl.appendChild(card);
      });
      // count + total
      var total=dons.reduce(function(s,x){return s+(parseFloat(x.amount)||0)},0);
      var cur=(dons[0]&&dons[0].currency)||'¥';
      g('lf-total').textContent=dons.length+' donation'+(dons.length!==1?'s':'')+' · '+fmtAmt(total,cur);
    } else {
      g('lf-total').textContent='';
    }

    // ─ TOP 5 ─
    var topEl=g('lc-top');
    var tops=d.top_donors||[];
    if(!tops.length&&dons.length){
      // auto-compute from donations if not provided
      var map={};
      dons.forEach(function(x){
        map[x.user]=(map[x.user]||0)+(parseFloat(x.amount)||0);
      });
      var cur0=(dons[0]&&dons[0].currency)||'¥';
      tops=Object.keys(map).sort(function(a,b){return map[b]-map[a]}).slice(0,5).map(function(u,i){
        return{rank:i+1,user:u,total:map[u],currency:cur0};
      });
    }
    if(tops.length){
      topEl.innerHTML='';
      var maxAmt=tops.reduce(function(m,x){return Math.max(m,parseFloat(x.total)||0)},1);
      tops.slice(0,5).forEach(function(t,i){
        var pct=Math.round(((parseFloat(t.total)||0)/maxAmt)*100);
        var item=document.createElement('div');item.className='top-item';
        item.innerHTML='<div class="top-rank">'+RANKS[i]+'</div><div class="top-name">'+esc(t.user||'—')+'</div><div class="top-bar-wrap"><div class="top-bar" style="width:'+pct+'%"></div></div><div class="top-total">'+fmtAmt(t.total,t.currency)+'</div>';
        topEl.appendChild(item);
      });
    }

    // label
    g('lf-label').textContent=isLive?'🔴 Streaming Now':'⚫ Offline';

    // auto-open
    LC.toggle();
  }
};

function esc(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

document.addEventListener('DOMContentLoaded',LC.init);
if(document.readyState!=='loading')LC.init();
</script>
</body>
</html>

